// Merging LocalStorage custom data (Agent 1 functionality)
try {
    const customStudents = localStorage.getItem('ICEP_STUDENTS_CUSTOM');
    if (customStudents) {
        const parsed = JSON.parse(customStudents);
        ICEP_STUDENTS.push(...parsed);
    }
    const customTimetable = localStorage.getItem('ICEP_TIMETABLE_CUSTOM');
    if (customTimetable) {
        const parsed = JSON.parse(customTimetable);
        ICEP_TIMETABLE.push(...parsed);
    }
} catch(e) {
    console.error("Failed to load local storage data", e);
}

// Helper Functions
function getTimetableByDeptLevel(department, level) {
    return ICEP_TIMETABLE.filter(t => t.department === department && t.level === parseInt(level));
}

function saveTimetableEntry(entry) {
    let custom = [];
    try {
        const stored = localStorage.getItem('ICEP_TIMETABLE_CUSTOM');
        if (stored) custom = JSON.parse(stored);
    } catch(e) {}
    custom.push(entry);
    localStorage.setItem('ICEP_TIMETABLE_CUSTOM', JSON.stringify(custom));
    ICEP_TIMETABLE.push(entry);
}

function loadTimetable() {
    return ICEP_TIMETABLE;
}
